}; return {
    setup() {
        const loading = ref(true);
        const transformMode = ref('translate');
        const selectedObject = ref(null);

        let scene, camera, renderer, orbitControls, transformControls;
        let raycaster, mouse;
        const objects = [];

        const loadScript = (src) => {
            return new Promise((resolve, reject) => {
                if (document.querySelector(`script[src="${src}"]`)) { resolve(); return; }
                const script = document.createElement('script');
                script.src = src;
                script.onload = resolve;
                script.onerror = reject;
                document.head.appendChild(script);
            });
        };

        const initThree = () => {
            const el = document.getElementById('three-container');
            if (!el) return;
            el.innerHTML = '';

            scene = new window.THREE.Scene();
            scene.background = new window.THREE.Color(0x1a1a1a);

            camera = new window.THREE.PerspectiveCamera(50, el.clientWidth / el.clientHeight, 0.1, 10000);
            camera.position.set(500, 400, 500);

            renderer = new window.THREE.WebGLRenderer({ antialias: true });
            renderer.setSize(el.clientWidth, el.clientHeight);
            renderer.setPixelRatio(window.devicePixelRatio);

            // Gölgeleri açalım
            renderer.shadowMap.enabled = true;
            renderer.shadowMap.type = window.THREE.PCFSoftShadowMap;
            el.appendChild(renderer.domElement);

            // Aydınlatma (Lights)
            const ambientLight = new window.THREE.AmbientLight(0x404040, 1.5);
            scene.add(ambientLight);

            const dirLight = new window.THREE.DirectionalLight(0xffffff, 2);
            dirLight.position.set(300, 500, 400);
            dirLight.castShadow = true;
            dirLight.shadow.mapSize.width = 2048;
            dirLight.shadow.mapSize.height = 2048;
            dirLight.shadow.camera.left = -500;
            dirLight.shadow.camera.right = 500;
            dirLight.shadow.camera.top = 500;
            dirLight.shadow.camera.bottom = -500;
            scene.add(dirLight);

            // Zemin ve Izgara
            const gridHelper = new window.THREE.GridHelper(2000, 40, 0x444444, 0x222222);
            scene.add(gridHelper);

            const floorGeo = new window.THREE.PlaneGeometry(2000, 2000);
            const floorMat = new window.THREE.MeshStandardMaterial({ color: 0x111111, side: window.THREE.DoubleSide });
            const floor = new window.THREE.Mesh(floorGeo, floorMat);
            floor.rotation.x = -Math.PI / 2;
            floor.receiveShadow = true;
            scene.add(floor);

            // Orbit Controls (Kamera için)
            orbitControls = new window.THREE.OrbitControls(camera, renderer.domElement);
            orbitControls.enableDamping = true;
            orbitControls.dampingFactor = 0.05;

            // Transform Controls (Objeleri hareket ettirmek için Kırmızı/Yeşil/Mavi oklar)
            transformControls = new window.THREE.TransformControls(camera, renderer.domElement);

            // Kullanıcı transform oklarından birini tuttuğunda kameranın dönmesini engelle
            transformControls.addEventListener('dragging-changed', (event) => {
                orbitControls.enabled = !event.value;
            });
            scene.add(transformControls);

            // Raycaster (Fare Tıklamalarını Algılamak için)
            raycaster = new window.THREE.Raycaster();
            mouse = new window.THREE.Vector2();

            // Fare tıklama olayını dinle
            renderer.domElement.addEventListener('pointerdown', onPointerDown);
            window.addEventListener('resize', onWindowResize);

            const animate = () => {
                requestAnimationFrame(animate);
                orbitControls.update();
                renderer.render(scene, camera);
            };
            animate();
        };

        const onPointerDown = (event) => {
            // Eğer kullanıcı transform (taşıma) oklarına tıklıyorsa, seçim işlemini iptal et
            if (transformControls.axis !== null) return;

            const el = document.getElementById('three-container');
            const rect = el.getBoundingClientRect();

            // Farenin tarayıcıdaki konumunu Three.js'in anlayacağı -1 ile 1 arasındaki vektöre çevir
            mouse.x = ((event.clientX - rect.left) / el.clientWidth) * 2 - 1;
            mouse.y = -((event.clientY - rect.top) / el.clientHeight) * 2 + 1;

            raycaster.setFromCamera(mouse, camera);

            // Sadece sahneye bizim eklediğimiz objeleri kontrol et
            const intersects = raycaster.intersectObjects(objects, false);

            if (intersects.length > 0) {
                const object = intersects[0].object;
                if (transformControls.object !== object) {
                    // Seçilen objeye Gizmo oklarını bağla
                    transformControls.attach(object);
                    selectedObject.value = object.uuid;

                    // Seçilen objeyi hafifçe aydınlat (Vurgu)
                    objects.forEach(obj => obj.material.emissive.setHex(0x000000));
                    object.material.emissive.setHex(0x333333);
                }
            } else {
                // Boşluğa tıklandıysa seçimi kaldır
                transformControls.detach();
                selectedObject.value = null;
                objects.forEach(obj => obj.material.emissive.setHex(0x000000));
            }
        };

        const onWindowResize = () => {
            const el = document.getElementById('three-container');
            if (!el || !camera || !renderer) return;
            camera.aspect = el.clientWidth / el.clientHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(el.clientWidth, el.clientHeight);
        };

        const setMode = (mode) => {
            if (!mode) {
                transformMode.value = 'translate';
                mode = 'translate';
            }
            if (transformControls) transformControls.setMode(mode);
        };

        const getRandomColor = () => {
            // Endüstriyel mat renkler
            const colors = [0xe74c3c, 0x3498db, 0x2ecc71, 0xf1c40f, 0x9b59b6, 0xe67e22, 0xecf0f1];
            return colors[Math.floor(Math.random() * colors.length)];
        };

        const addShape = (type) => {
            let geometry;
            switch(type) {
                case 'cube': geometry = new window.THREE.BoxGeometry(100, 100, 100); break;
                case 'sphere': geometry = new window.THREE.SphereGeometry(60, 32, 32); break;
                case 'cylinder': geometry = new window.THREE.CylinderGeometry(50, 50, 100, 32); break;
            }

            const material = new window.THREE.MeshStandardMaterial({
                color: getRandomColor(),
                metalness: 0.2,
                roughness: 0.3
            });

            const mesh = new window.THREE.Mesh(geometry, material);
            mesh.position.y = 50;
            mesh.castShadow = true;
            mesh.receiveShadow = true;

            scene.add(mesh);
            objects.push(mesh);

            // Yeni eklenen objeyi otomatik seç
            transformControls.attach(mesh);
            selectedObject.value = mesh.uuid;
            objects.forEach(obj => obj.material.emissive.setHex(0x000000));
            mesh.material.emissive.setHex(0x333333);
        };

        const deleteSelected = () => {
            if (!transformControls.object) return;
            const obj = transformControls.object;

            transformControls.detach();
            selectedObject.value = null;

            scene.remove(obj);
            const index = objects.indexOf(obj);
            if (index > -1) objects.splice(index, 1);

            // Belleği temizle (Memory leak'i önler)
            obj.geometry.dispose();
            obj.material.dispose();
        };

        const clearScene = () => {
            transformControls.detach();
            selectedObject.value = null;

            objects.forEach(obj => {
                scene.remove(obj);
                obj.geometry.dispose();
                obj.material.dispose();
            });
            objects.length = 0;
        };

        onMounted(async () => {
            try {
                await loadScript('https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js');
                await loadScript('https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/controls/OrbitControls.js');
                await loadScript('https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/controls/TransformControls.js');

                initThree();
                loading.value = false;
            } catch (e) {
                console.error("Yükleme hatası", e);
            }
        });

        onUnmounted(() => {
            window.removeEventListener('resize', onWindowResize);
            if (renderer) {
                const el = renderer.domElement;
                if(el) el.removeEventListener('pointerdown', onPointerDown);
                renderer.dispose();
            }
        });

        return {
            loading, transformMode, selectedObject,
            addShape, setMode, deleteSelected, clearScene
        };
    }
}; function __dummy() {
